#include <functional>
#include <iostream>

int add(int a, int b) {
    return a + b;
}

int main() {
    auto bound_func = std::bind(add, 5, std::placeholders::_1);  // Binds 5 as the first argument, leaves second for runtime
    int result = bound_func(10);  // Calls add(5, 10)
    std::cout << result << std::endl;  // Outputs 15
    return 0;
}
